#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
int main(int argc,const char **argv) { @autoreleasepool {
 if(argc!=5)return 2;id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*e=nil;fprintf(stderr,"device=%s\n",d.name.UTF8String);
 id<MTLLibrary>l=[d newLibraryWithURL:[NSURL fileURLWithPath:@(argv[1])] error:&e];if(!l){fprintf(stderr,"%s\n",e.description.UTF8String);return 3;}
 id<MTLComputePipelineState>p=[d newComputePipelineStateWithFunction:[l newFunctionWithName:@"probe"] error:&e];if(!p){fprintf(stderr,"%s\n",e.description.UTF8String);return 4;}
 NSData*data=[NSData dataWithContentsOfFile:@(argv[2])];NSUInteger n=data.length/8;id<MTLBuffer>coords=[d newBufferWithBytes:data.bytes length:data.length options:MTLResourceStorageModeShared],out=[d newBufferWithLength:n*16 options:MTLResourceStorageModeShared];
 BOOL array=atoi(argv[4]);MTLTextureDescriptor*td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA32Float width:9 height:7 mipmapped:NO];td.storageMode=MTLStorageModeShared;td.usage=MTLTextureUsageShaderRead;if(array){td.textureType=MTLTextureType2DArray;td.arrayLength=2;}id<MTLTexture>t=[d newTextureWithDescriptor:td];
 for(unsigned layer=0;layer<(array?2:1);layer++){float pixels[9*7*4];for(unsigned y=0;y<7;y++)for(unsigned x=0;x<9;x++)for(unsigned c=0;c<4;c++)pixels[(y*9+x)*4+c]=(float)((int)(layer*1000+y*37+x*7+c)-300)/997.0f;[t replaceRegion:MTLRegionMake2D(0,0,9,7) mipmapLevel:0 slice:layer withBytes:pixels bytesPerRow:9*16 bytesPerImage:9*7*16];}
 id<MTLCommandQueue>q=[d newCommandQueue];id<MTLCommandBuffer>b=[q commandBuffer];id<MTLComputeCommandEncoder>ce=[b computeCommandEncoder];[ce setComputePipelineState:p];[ce setTexture:t atIndex:0];[ce setBuffer:coords offset:0 atIndex:0];[ce setBuffer:out offset:0 atIndex:1];[ce dispatchThreadgroups:MTLSizeMake((n+31)/32,1,1) threadsPerThreadgroup:MTLSizeMake(32,1,1)];[ce endEncoding];[b commit];[b waitUntilCompleted];if(b.status!=MTLCommandBufferStatusCompleted){fprintf(stderr,"%s\n",b.error.description.UTF8String);return 5;}[[NSData dataWithBytes:out.contents length:n*16] writeToFile:@(argv[3]) atomically:YES];fprintf(stderr,"samples=%lu OK\n",(unsigned long)n);return 0;
}}
